#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={1,2,3,4},count={1,2,4,5};
double beta=0.1;
for(int step=0;step<12;step++){
    double gradient=0,hessian=0;
    for(int i=0;i<int(x.size());i++){
        double mean=exp(beta*x[i]);
        gradient+=(mean-count[i])*x[i];
        hessian+=mean*x[i]*x[i];
    }
    if(hessian<=0)return 1;
    beta-=gradient/hessian;
}
cout<<fixed<<setprecision(7)<<beta<<"
";
return 0;
}

