#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={-2,-1,1,2},y={0,0,1,1};
double beta=0;
for(int iteration=0;iteration<10;iteration++){
    double gradient=0,information=0;
    for(int i=0;i<int(x.size());i++){
        double p=1/(1+exp(-beta*x[i]));
        gradient+=(p-y[i])*x[i];
        information+=p*(1-p)*x[i]*x[i];
    }
    if(information<1e-10)break;
    beta-=gradient/information;
}
cout<<"coefficient "<<beta<<"
";
return 0;
}

