#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={0,1,2},y={2,3.2,5.4};
double amplitude=1.5,growth=0.3,step=0.002;
for(int iteration=0;iteration<500;iteration++){
    double gradA=0,gradB=0;
    for(int i=0;i<int(x.size());i++){
        double ex=exp(growth*x[i]);
        double residual=amplitude*ex-y[i];
        gradA+=residual*ex/x.size();
        gradB+=residual*amplitude*x[i]*ex/x.size();
    }
    amplitude-=step*gradA;
    growth-=step*gradB;
}
cout<<amplitude<<" "<<growth<<"
";
return 0;
}

