#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>instrument={-2,-1,0,1,2,3},endogenous={-0.1,0.2,0.0,0.1,0.0,0.2};
double mx=0,mz=0,xx=0,zz=0,xz=0;
for(int i=0;i<int(instrument.size());i++){
    mx+=endogenous[i]/endogenous.size();mz+=instrument[i]/instrument.size();
}
for(int i=0;i<int(instrument.size());i++){
    double a=endogenous[i]-mx,b=instrument[i]-mz;
    xx+=a*a;zz+=b*b;xz+=a*b;
}
double r2=xz*xz/(xx*zz);
double f=(r2/(1-r2))*(instrument.size()-2);
cout<<"first-stage R2 "<<r2<<" F "<<f<<"
";
return 0;
}

